CREATE DATABASE SportZone COLLATE Vietnamese_CI_AS;
GO
USE SportZone;
GO

/* ---------------- PHẦN 2. TẠO BẢNG ---------------- */
IF OBJECT_ID(N'[__EFMigrationsHistory]') IS NULL
BEGIN
    CREATE TABLE [__EFMigrationsHistory] (
        [MigrationId] nvarchar(150) NOT NULL,
        [ProductVersion] nvarchar(32) NOT NULL,
        CONSTRAINT [PK___EFMigrationsHistory] PRIMARY KEY ([MigrationId])
    );
END;
GO

BEGIN TRANSACTION;
CREATE TABLE [DichVu] (
    [MaDV] int NOT NULL IDENTITY,
    [TenDV] nvarchar(100) NOT NULL,
    [DonVi] nvarchar(20) NOT NULL,
    [DonGia] decimal(18,0) NOT NULL,
    CONSTRAINT [PK_DichVu] PRIMARY KEY ([MaDV])
);

CREATE TABLE [KhachHang] (
    [MaKH] int NOT NULL IDENTITY,
    [HoTen] nvarchar(100) NOT NULL,
    [SDT] varchar(15) NOT NULL,
    [Email] nvarchar(100) NULL,
    [MatKhauHash] varchar(100) NULL,
    [DiemTichLuy] int NOT NULL,
    CONSTRAINT [PK_KhachHang] PRIMARY KEY ([MaKH])
);

CREATE TABLE [KhungGio] (
    [MaKhungGio] int NOT NULL IDENTITY,
    [TenKhungGio] nvarchar(50) NOT NULL,
    [GioBatDau] time NOT NULL,
    [GioKetThuc] time NOT NULL,
    CONSTRAINT [PK_KhungGio] PRIMARY KEY ([MaKhungGio]),
    CONSTRAINT [CK_KhungGio_Gio] CHECK (GioKetThuc > GioBatDau)
);

CREATE TABLE [LoaiSan] (
    [MaLoai] int NOT NULL IDENTITY,
    [TenLoai] nvarchar(50) NOT NULL,
    [MoTa] nvarchar(500) NULL,
    CONSTRAINT [PK_LoaiSan] PRIMARY KEY ([MaLoai])
);

CREATE TABLE [VaiTro] (
    [MaVaiTro] int NOT NULL IDENTITY,
    [TenVaiTro] nvarchar(50) NOT NULL,
    CONSTRAINT [PK_VaiTro] PRIMARY KEY ([MaVaiTro])
);

CREATE TABLE [BangGia] (
    [MaLoai] int NOT NULL,
    [MaKhungGio] int NOT NULL,
    [LaCuoiTuan] bit NOT NULL,
    [GiaMoiGio] decimal(18,0) NOT NULL,
    CONSTRAINT [PK_BangGia] PRIMARY KEY ([MaLoai], [MaKhungGio], [LaCuoiTuan]),
    CONSTRAINT [CK_BangGia_Gia] CHECK (GiaMoiGio >= 0),
    CONSTRAINT [FK_BangGia_KhungGio_MaKhungGio] FOREIGN KEY ([MaKhungGio]) REFERENCES [KhungGio] ([MaKhungGio]) ON DELETE NO ACTION,
    CONSTRAINT [FK_BangGia_LoaiSan_MaLoai] FOREIGN KEY ([MaLoai]) REFERENCES [LoaiSan] ([MaLoai]) ON DELETE NO ACTION
);

CREATE TABLE [San] (
    [MaSan] int NOT NULL IDENTITY,
    [TenSan] nvarchar(50) NOT NULL,
    [MaLoai] int NOT NULL,
    [HinhAnh] nvarchar(255) NULL,
    [MoTa] nvarchar(500) NULL,
    [TrangThai] nvarchar(20) NOT NULL,
    CONSTRAINT [PK_San] PRIMARY KEY ([MaSan]),
    CONSTRAINT [FK_San_LoaiSan_MaLoai] FOREIGN KEY ([MaLoai]) REFERENCES [LoaiSan] ([MaLoai]) ON DELETE NO ACTION
);

CREATE TABLE [NhanVien] (
    [MaNV] int NOT NULL IDENTITY,
    [HoTen] nvarchar(100) NOT NULL,
    [TenDangNhap] nvarchar(50) NOT NULL,
    [MatKhauHash] varchar(100) NOT NULL,
    [MaVaiTro] int NOT NULL,
    [TrangThai] nvarchar(20) NOT NULL,
    CONSTRAINT [PK_NhanVien] PRIMARY KEY ([MaNV]),
    CONSTRAINT [FK_NhanVien_VaiTro_MaVaiTro] FOREIGN KEY ([MaVaiTro]) REFERENCES [VaiTro] ([MaVaiTro]) ON DELETE NO ACTION
);

CREATE TABLE [LichDinhKy] (
    [MaLich] int NOT NULL IDENTITY,
    [MaKH] int NOT NULL,
    [MaSan] int NOT NULL,
    [ThuTrongTuan] tinyint NOT NULL,
    [GioBatDau] time NOT NULL,
    [GioKetThuc] time NOT NULL,
    [TuNgay] date NOT NULL,
    [DenNgay] date NOT NULL,
    CONSTRAINT [PK_LichDinhKy] PRIMARY KEY ([MaLich]),
    CONSTRAINT [CK_LichDinhKy_Ngay] CHECK (DenNgay >= TuNgay),
    CONSTRAINT [CK_LichDinhKy_Thu] CHECK (ThuTrongTuan BETWEEN 1 AND 7),
    CONSTRAINT [FK_LichDinhKy_KhachHang_MaKH] FOREIGN KEY ([MaKH]) REFERENCES [KhachHang] ([MaKH]) ON DELETE NO ACTION,
    CONSTRAINT [FK_LichDinhKy_San_MaSan] FOREIGN KEY ([MaSan]) REFERENCES [San] ([MaSan]) ON DELETE NO ACTION
);

CREATE TABLE [DatSan] (
    [MaDatSan] int NOT NULL IDENTITY,
    [MaKH] int NOT NULL,
    [MaSan] int NOT NULL,
    [NgaySuDung] date NOT NULL,
    [GioBatDau] time NOT NULL,
    [GioKetThuc] time NOT NULL,
    [TienSan] decimal(18,0) NOT NULL,
    [TienCoc] decimal(18,0) NOT NULL,
    [TrangThai] nvarchar(20) NOT NULL,
    [NgayTao] datetime2 NOT NULL,
    [MaNVXacNhan] int NULL,
    [MaLichDinhKy] int NULL,
    CONSTRAINT [PK_DatSan] PRIMARY KEY ([MaDatSan]),
    CONSTRAINT [CK_DatSan_Gio] CHECK (GioKetThuc > GioBatDau),
    CONSTRAINT [FK_DatSan_KhachHang_MaKH] FOREIGN KEY ([MaKH]) REFERENCES [KhachHang] ([MaKH]) ON DELETE NO ACTION,
    CONSTRAINT [FK_DatSan_LichDinhKy_MaLichDinhKy] FOREIGN KEY ([MaLichDinhKy]) REFERENCES [LichDinhKy] ([MaLich]) ON DELETE NO ACTION,
    CONSTRAINT [FK_DatSan_NhanVien_MaNVXacNhan] FOREIGN KEY ([MaNVXacNhan]) REFERENCES [NhanVien] ([MaNV]) ON DELETE NO ACTION,
    CONSTRAINT [FK_DatSan_San_MaSan] FOREIGN KEY ([MaSan]) REFERENCES [San] ([MaSan]) ON DELETE NO ACTION
);

CREATE TABLE [ChiTietDichVu] (
    [MaDatSan] int NOT NULL,
    [MaDV] int NOT NULL,
    [SoLuong] int NOT NULL,
    [DonGia] decimal(18,0) NOT NULL,
    CONSTRAINT [PK_ChiTietDichVu] PRIMARY KEY ([MaDatSan], [MaDV]),
    CONSTRAINT [CK_ChiTietDichVu_SoLuong] CHECK (SoLuong > 0),
    CONSTRAINT [FK_ChiTietDichVu_DatSan_MaDatSan] FOREIGN KEY ([MaDatSan]) REFERENCES [DatSan] ([MaDatSan]) ON DELETE NO ACTION,
    CONSTRAINT [FK_ChiTietDichVu_DichVu_MaDV] FOREIGN KEY ([MaDV]) REFERENCES [DichVu] ([MaDV]) ON DELETE NO ACTION
);

CREATE TABLE [HoaDon] (
    [MaHD] int NOT NULL IDENTITY,
    [MaDatSan] int NOT NULL,
    [MaNV] int NOT NULL,
    [NgayLap] datetime2 NOT NULL,
    [TongTien] decimal(18,0) NOT NULL,
    [PhuongThucTT] nvarchar(20) NOT NULL,
    CONSTRAINT [PK_HoaDon] PRIMARY KEY ([MaHD]),
    CONSTRAINT [FK_HoaDon_DatSan_MaDatSan] FOREIGN KEY ([MaDatSan]) REFERENCES [DatSan] ([MaDatSan]) ON DELETE NO ACTION,
    CONSTRAINT [FK_HoaDon_NhanVien_MaNV] FOREIGN KEY ([MaNV]) REFERENCES [NhanVien] ([MaNV]) ON DELETE NO ACTION
);

CREATE INDEX [IX_BangGia_MaKhungGio] ON [BangGia] ([MaKhungGio]);

CREATE INDEX [IX_ChiTietDichVu_MaDV] ON [ChiTietDichVu] ([MaDV]);

CREATE INDEX [IX_DatSan_MaKH] ON [DatSan] ([MaKH]);

CREATE INDEX [IX_DatSan_MaLichDinhKy] ON [DatSan] ([MaLichDinhKy]);

CREATE INDEX [IX_DatSan_MaNVXacNhan] ON [DatSan] ([MaNVXacNhan]);

CREATE INDEX [IX_DatSan_MaSan_NgaySuDung_TrangThai] ON [DatSan] ([MaSan], [NgaySuDung], [TrangThai]);

CREATE UNIQUE INDEX [IX_HoaDon_MaDatSan] ON [HoaDon] ([MaDatSan]);

CREATE INDEX [IX_HoaDon_MaNV] ON [HoaDon] ([MaNV]);

CREATE UNIQUE INDEX [IX_KhachHang_SDT] ON [KhachHang] ([SDT]);

CREATE INDEX [IX_LichDinhKy_MaKH] ON [LichDinhKy] ([MaKH]);

CREATE INDEX [IX_LichDinhKy_MaSan] ON [LichDinhKy] ([MaSan]);

CREATE INDEX [IX_NhanVien_MaVaiTro] ON [NhanVien] ([MaVaiTro]);

CREATE UNIQUE INDEX [IX_NhanVien_TenDangNhap] ON [NhanVien] ([TenDangNhap]);

CREATE INDEX [IX_San_MaLoai] ON [San] ([MaLoai]);

VALUES (N'20261026150259_KhoiTao', N'10.0.14');

COMMIT;
GO

