/* ---------------- PHẦN 4. VIEW BÁO CÁO ---------------- */

-- Doanh thu theo ngày (UC29): doanh thu = tiền sân + dịch vụ, ghi trong HoaDon.TongTien
CREATE VIEW vw_DoanhThuTheoNgay AS
SELECT CAST(h.NgayLap AS date) AS Ngay,
       COUNT(*)                AS SoHoaDon,
       SUM(h.TongTien)         AS DoanhThu
FROM HoaDon h
GROUP BY CAST(h.NgayLap AS date);
GO

-- Lịch sân: mỗi đơn chưa hủy kèm tên sân, khách (dùng để xem nhanh lịch một ngày)
CREATE VIEW vw_LichSan AS
SELECT d.MaDatSan, d.NgaySuDung, d.GioBatDau, d.GioKetThuc,
       s.TenSan, l.TenLoai, k.HoTen AS KhachHang, k.SDT,
       d.TienSan, d.TienCoc, d.TrangThai
FROM DatSan d
JOIN San s       ON s.MaSan = d.MaSan
JOIN LoaiSan l   ON l.MaLoai = s.MaLoai
JOIN KhachHang k ON k.MaKH = d.MaKH
WHERE d.TrangThai <> N'Đã hủy';
GO

/* ---------------- KIỂM TRA SAU KHI CHẠY ---------------- */
SELECT 'VaiTro' AS Bang, COUNT(*) AS SoDong FROM VaiTro
UNION ALL SELECT 'NhanVien', COUNT(*) FROM NhanVien
UNION ALL SELECT 'KhachHang', COUNT(*) FROM KhachHang
UNION ALL SELECT 'LoaiSan', COUNT(*) FROM LoaiSan
UNION ALL SELECT 'San', COUNT(*) FROM San
UNION ALL SELECT 'KhungGio', COUNT(*) FROM KhungGio
UNION ALL SELECT 'BangGia', COUNT(*) FROM BangGia
UNION ALL SELECT 'DatSan', COUNT(*) FROM DatSan
UNION ALL SELECT 'DichVu', COUNT(*) FROM DichVu
UNION ALL SELECT 'ChiTietDichVu', COUNT(*) FROM ChiTietDichVu
UNION ALL SELECT 'HoaDon', COUNT(*) FROM HoaDon
UNION ALL SELECT 'LichDinhKy', COUNT(*) FROM LichDinhKy;

SELECT TOP 7 * FROM vw_DoanhThuTheoNgay ORDER BY Ngay DESC;
GO
